export const meta = {
  name: 'dreaming-run',
  description: 'ClaudeDream: one analyzer per transcript part into its project memory, then one organizer per project',
  phases: [
    { title: 'Analyze', detail: 'one dreaming:analyzer per transcript part; per project, groups of about 20, each group finished before the next' },
    { title: 'Organize', detail: 'one dreaming:organizer per memory directory, after that directory\'s analyzers finish' },
  ],
}

// Generated by prepare: every part and the staging copy of the memory directory it goes to.
// The rules of the cookbook's work_request.md live here: one analyzer per transcript, groups of
// about 20 finished one after another, the organizer once after the analyzers; an agent that fails
// is recorded with its reason and does not stop the run.
const PLAN = __PLAN__
const GROUP = 20

const SUMMARY = { type: 'object', properties: { summary: { type: 'string' } }, required: ['summary'] }
const ORGANIZED = {
  type: 'object',
  properties: { index_entries: { type: 'integer' }, changes: { type: 'array', items: { type: 'string' } } },
  required: ['index_entries', 'changes'],
}

function analyzeTask(part, dir) {
  return `Please read the transcript at ${part.path} and add the durable, verified facts it shows to the long-term memory directory at ${dir}. Other analyzers are working on other transcripts into the same directory at the same time, so check what is already there before writing and add to or update existing files rather than overwrite them. Write only inside that directory, and do not modify the transcript. When done, submit a short summary of what you added.` +
    // Added by ClaudeDream (not in the cookbook): the transcript files are deleted after the run, and
    // today is the day of the dream, not the day things happened.
    ` When you note where a fact came from, name the session by its title and its dates, from the SESSION and NOTE ABOUT THIS FILE lines at the top of the transcript; do not cite the transcript's file name or part number, which will not exist after this run, and date facts by when they happened in the session, not by today's date.`
}

function organizeTask(dir) {
  return `The analyzers have finished adding this run's facts to the memory directory at ${dir}. Organize that directory as your instructions say, and report your changes.` +
    // Added by ClaudeDream (not in the cookbook): the analyzers tend to put a dated update line under an
    // older statement it replaces and leave that statement standing; the organizer's own rule says to
    // keep the current value and note what it replaced.
    ` Analyzers often added a dated update line below an older statement that it replaces, and left the older statement standing. Wherever a later line, in the same file or in another, replaces or corrects an earlier statement, rewrite the earlier statement so that the file reads as the current understanding, and keep what it replaced as one short line with its date and source, as your rules say. Do not leave a replaced statement standing as if it were current, and do not drop a fact that is still true.`
}

async function runGroup(g) {
  const analyzed = [], failed = []
  for (let i = 0; i < g.parts.length; i += GROUP) {
    const batch = g.parts.slice(i, i + GROUP)
    const results = await parallel(batch.map(p => () =>
      agent(analyzeTask(p, g.stage), { agentType: 'dreaming:analyzer', label: `analyze ${p.id}`, phase: 'Analyze', schema: SUMMARY })))
    results.forEach((r, k) => (r ? analyzed : failed).push(batch[k].id))
  }
  const org = await agent(organizeTask(g.stage), { agentType: 'dreaming:organizer', label: `organize ${g.key}`, phase: 'Organize', schema: ORGANIZED })
  return { key: g.key, analyzed: analyzed.length, failed, organized: !!org, index_entries: org ? org.index_entries : null }
}

const groups = await parallel(PLAN.groups.map(g => () => runGroup(g)))
const done = groups.filter(Boolean)
log(`analyzed ${done.reduce((n, g) => n + g.analyzed, 0)} parts; ${done.reduce((n, g) => n + g.failed.length, 0)} failed`)
return { groups: done, missing_groups: PLAN.groups.length - done.length }
